package cn.interview;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.stereotype.Service;
import java.util.*;
import static cn.interview.Models.*;

@Service
class DesignPracticeService implements V2ModelHandler {
    static final List<String> STAGES=List.of("CLARIFY","CONSTRAINTS","ENTITIES_API","ARCHITECTURE","TRADEOFFS");
    static final List<String> LABELS=List.of("需求澄清","约束与容量","核心实体与 API","架构与数据流","故障、恢复与权衡");
    static final List<List<String>> FIELD_IDS=List.of(List.of("goals","useCases","outOfScope","openQuestions"),List.of("constraints","capacityAssumptions","basis"),List.of("entities","operations","ioErrors"),List.of("components","dataFlow","stateBoundaries"),List.of("failures","recovery","alternatives","tradeoffs"));
    static final List<List<String>> FIELD_LABELS=List.of(List.of("目标","主要用例","范围外事项","待澄清点（没有请写无）"),List.of("功能与非功能约束","容量或成本假设（未知可写验证办法）","假设依据"),List.of("核心实体","操作或 API","输入、输出与错误"),List.of("组件职责","关键数据流","存储或状态边界"),List.of("故障场景","恢复办法","备选方案","取舍与局限"));
    final V2Store db;final V2Operations ops;final V2ModelRunner runner;
    DesignPracticeService(V2Store db,V2Operations ops,V2ModelRunner runner){this.db=db;this.ops=ops;this.runner=runner;}
    ArrayNode scenarios(){var out=db.array();out.addObject().put("id","ORDER_SERVICE").put("version","v2.1").put("title","订单服务设计").put("synthetic",true).put("description","合成场景：为在线商店设计创建订单、查询订单与支付状态更新。容量、可用性与一致性约束待用户澄清；不得把假设当成已给定数字。");out.addObject().put("id","KNOWLEDGE_AGENT").put("version","v2.1").put("title","知识库 Agent 设计").put("synthetic",true).put("description","合成场景：设计基于企业知识库的问答 Agent，需考虑检索依据、工具权限、状态恢复及失败。工具与数据边界需用户明确假设，不代表本机具有外部执行能力。");return out;}
    ObjectNode create(JsonNode body){return ops.write("DESIGN_SESSION","LOCAL_USER",body,()->{String scenario=choice(required(body,"scenarioId",40),"ORDER_SERVICE","KNOWLEDGE_AGENT");String version=optional(body,"scenarioVersion","v2.1",30);if(!version.equals("v2.1"))throw V2Exception.conflict("V2_SCENARIO_CHANGED","案例版本不受支持，请重新选择");var row=db.object().put("scenarioId",scenario).put("scenarioVersion",version).put("state","IN_PROGRESS").put("currentStage","CLARIFY").put("constraints",optional(body,"constraints","",6000)).put("mock",runner.llm.legacy.isMock()).put("synthetic",true);for(JsonNode s:scenarios())if(s.path("id").asText().equals(scenario))row.set("scenario",s.deepCopy());var stages=row.putArray("stages");for(int i=0;i<5;i++){var stage=stages.addObject().put("id",STAGES.get(i)).put("title",LABELS.get(i)).put("state","EMPTY").put("currentArtifactVersion",0);stage.putObject("draft");stage.putArray("artifactVersions");var fields=stage.putArray("fieldDefinitions");for(int j=0;j<FIELD_IDS.get(i).size();j++)fields.addObject().put("id",FIELD_IDS.get(i).get(j)).put("label",FIELD_LABELS.get(i).get(j));if(i==4&&scenario.equals("KNOWLEDGE_AGENT"))fields.addObject().put("id","agentTools").put("label","工具权限与调用失败");}return db.insert("v2_design_sessions",row);});}
    ObjectNode stage(JsonNode session,String id){int index=STAGES.indexOf(id);if(index<0)throw V2Exception.invalid("未知设计阶段");return (ObjectNode)session.path("stages").get(index);}
    void editable(JsonNode session){if(!session.path("state").asText().equals("IN_PROGRESS"))throw V2Exception.conflict("V2_INVALID_STATE","已结束训练只读；再次练习请建立新训练");for(JsonNode s:session.path("stages"))if(s.path("state").asText().equals("FEEDBACK_PENDING"))throw V2Exception.conflict("V2_RESOURCE_BUSY","当前反馈正在生成，请保留本页文本并查看操作状态");}
    ObjectNode fields(JsonNode stage,JsonNode raw,boolean required){if(!raw.isObject())throw V2Exception.invalid("请填写本阶段的结构化文本");var allowed=new HashSet<String>();stage.path("fieldDefinitions").forEach(f->allowed.add(f.path("id").asText()));raw.fieldNames().forEachRemaining(k->{if(!allowed.contains(k))throw V2Exception.invalid("字段不属于本阶段");});var result=db.object();int total=0;for(String key:allowed){String value=raw.has(key)?PracticeService.text(raw,key,6000,required):"";if(required&&value.isBlank())throw V2Exception.invalid("请补全本阶段必填字段："+key);total+=value.length();result.put(key,value);}if(total>6000)throw V2Exception.invalid("阶段产物合计不超过6000字符");return result;}
    ObjectNode draft(String id,JsonNode body){return view(ops.write("DESIGN_DRAFT",id,body,()->{var session=db.get("v2_design_sessions",id);db.expect(session,body);editable(session);String sid=required(body,"stageId",40);if(!session.path("currentStage").asText().equals(sid))throw V2Exception.conflict("V2_STAGE_CHANGED","请先回到当前阶段或明确重新打开前序阶段");var stage=stage(session,sid);stage.set("draft",fields(stage,body.path("artifact"),false));stage.put("state","DRAFT");return db.save("v2_design_sessions",session,session.path("revision").asInt());}));}
    ObjectNode latest(JsonNode stage){int version=stage.path("currentArtifactVersion").asInt();if(version<1)throw V2Exception.conflict("V2_STAGE_INCOMPLETE","阶段尚未提交有效产物");for(JsonNode artifact:stage.path("artifactVersions"))if(artifact.path("version").asInt()==version)return (ObjectNode)artifact;throw V2Exception.conflict("V2_STAGE_INCOMPLETE","阶段产物缺失");}
    ArrayNode vector(JsonNode session,int before){var out=db.array();for(int i=0;i<before;i++){var s=session.path("stages").get(i);out.addObject().put("stageId",s.path("id").asText()).put("artifactVersion",s.path("currentArtifactVersion").asInt());}return out;}
    void ready(JsonNode session,int index){var stage=session.path("stages").get(index);var artifact=latest(stage);if(!stage.path("state").asText().equals("FEEDBACK_READY")||!artifact.path("feedbackStatus").asText().equals("READY")||!artifact.path("dependencies").equals(vector(session,index)))throw V2Exception.conflict("V2_STAGE_STALE","本阶段反馈失败、尚未就绪或依赖已变；请逐阶段重新提交评估");}
    ObjectNode submit(String id,JsonNode body){return view(runner.run(V2Task.DESIGN_STAGE_EVALUATOR,"DESIGN_SUBMIT",id,body,()->{var session=db.get("v2_design_sessions",id);db.expect(session,body);editable(session);if(session.path("mock").asBoolean()!=runner.llm.legacy.isMock())throw V2Exception.conflict("V2_MODEL_MODE_CHANGED","当前模型模式与训练创建时不同");String sid=required(body,"stageId",40);if(!session.path("currentStage").asText().equals(sid))throw V2Exception.conflict("V2_STAGE_CHANGED","不能跳阶段提交");int index=STAGES.indexOf(sid);for(int i=0;i<index;i++)ready(session,i);var stage=stage(session,sid);JsonNode raw=body.path("reuseCurrentArtifact").asBoolean()?latest(stage).path("fields"):body.path("artifact");var fields=fields(stage,raw,true);if(stage.path("currentArtifactVersion").asInt()>0){var previous=latest(stage);if(Set.of("FAILED","INTERRUPTED").contains(previous.path("feedbackStatus").asText())&&previous.path("fields").equals(fields)&&previous.path("dependencies").equals(vector(session,index)))throw new V2Exception(409,"V2_RETRY_EXISTING_OPERATION","相同产物的反馈尚未完成，请查看原操作并显式重试；修改产物后才会创建新版本。","RETRY_OPERATION").detail("operationId",previous.path("operationId").asText()).detail("resourceId",id).detail("retryable",true);}if(stage.path("artifactVersions").size()>=20)throw new V2Exception(413,"V2_STAGE_LIMIT","本阶段已达20次提交，请新建训练；历史保留。","EDIT_INPUT");int number=stage.path("currentArtifactVersion").asInt()+1;var artifact=stage.withArray("artifactVersions").addObject().put("version",number).put("submittedAt",now()).put("feedbackStatus","PENDING");artifact.set("fields",fields);artifact.set("dependencies",vector(session,index));stage.put("currentArtifactVersion",number).put("state","FEEDBACK_PENDING");stage.set("draft",fields.deepCopy());stage.remove("staleReason");session.put("pendingStageId",sid).put("pendingArtifactVersion",number);
        var input=db.object().put("stageId",sid).put("constraints",session.path("constraints").asText());input.set("scenario",session.path("scenario").deepCopy());input.set("artifact",fields.deepCopy());var prior=input.putArray("previousArtifacts");for(int i=0;i<index;i++)prior.add(latest(session.path("stages").get(i)).path("fields").deepCopy());var rubric=input.putArray("rubric");for(JsonNode definition:stage.path("fieldDefinitions"))rubric.addObject().put("checkId",definition.path("id").asText()).put("description",definition.path("label").asText());var snapshots=input.putArray("snapshots");for(var it=fields.fields();it.hasNext();){var f=it.next();snapshots.addObject().put("id","artifact:"+sid+":"+number+":"+f.getKey()).put("text",f.getValue().asText()).put("purpose","ARTIFACT");}return new V2ModelRunner.Work("v2_design_sessions",session,input);
    }));}
    boolean open(JsonNode artifact){return !artifact.path("feedback").path("gaps").isEmpty()||!artifact.path("feedback").path("uncertain").isEmpty()||!artifact.path("feedback").path("openIssues").isEmpty();}
    void acknowledge(JsonNode session,int index,JsonNode body){ready(session,index);var stage=(ObjectNode)session.path("stages").get(index);var artifact=latest(stage);if(!body.path("artifactVersion").isIntegralNumber()||body.path("artifactVersion").asInt()!=artifact.path("version").asInt())throw V2Exception.conflict("V2_VERSION_CONFLICT","请核对本阶段提交版本");if(open(artifact)&&!body.path("acknowledgeOpenIssues").asBoolean())throw V2Exception.conflict("V2_OPEN_ISSUES","本阶段仍有缺口或未知，请明确确认带这些未解决项继续");stage.put("acknowledgedArtifactVersion",artifact.path("version").asInt());}
    ObjectNode advance(String id,JsonNode body){return view(ops.write("DESIGN_ADVANCE",id,body,()->{var session=db.get("v2_design_sessions",id);db.expect(session,body);editable(session);int index=STAGES.indexOf(session.path("currentStage").asText());if(index==4)throw V2Exception.conflict("V2_INVALID_STATE","已到最后阶段，请使用结束训练");acknowledge(session,index,body);session.put("currentStage",STAGES.get(index+1));return db.save("v2_design_sessions",session,session.path("revision").asInt());}));}
    ObjectNode reopen(String id,JsonNode body){return view(ops.write("DESIGN_REOPEN",id,body,()->{var session=db.get("v2_design_sessions",id);db.expect(session,body);editable(session);String sid=required(body,"stageId",40);int target=STAGES.indexOf(sid),current=STAGES.indexOf(session.path("currentStage").asText());if(target<0||target>current)throw V2Exception.conflict("V2_STAGE_CHANGED","只允许回到已到达阶段");if(!body.path("acknowledgeInvalidation").asBoolean())throw V2Exception.invalid("请确认修改前序产物会使后续反馈失效，历史仍保留");for(int i=target+1;i<5;i++){var stage=(ObjectNode)session.path("stages").get(i);if(stage.path("currentArtifactVersion").asInt()>0)stage.put("state","STALE").put("staleReason","前序阶段重新打开；需显式沿用或修改产物并重新评估");}var stage=stage(session,sid);if(stage.path("currentArtifactVersion").asInt()>0)stage.set("draft",latest(stage).path("fields").deepCopy());stage.put("state","DRAFT");session.put("currentStage",sid);return db.save("v2_design_sessions",session,session.path("revision").asInt());}));}
    ObjectNode finish(String id,JsonNode body){return view(ops.write("DESIGN_FINISH",id,body,()->{var session=db.get("v2_design_sessions",id);db.expect(session,body);editable(session);boolean early=body.path("early").asBoolean();if(early){session.put("earlyReason",required(body,"reason",1000)).put("state","ENDED_EARLY");}else{if(!session.path("currentStage").asText().equals("TRADEOFFS"))throw V2Exception.conflict("V2_STAGE_INCOMPLETE","尚未走完五阶段，请继续或选择提前结束");for(int i=0;i<5;i++){ready(session,i);if(i<4&&open(latest(session.path("stages").get(i)))&&session.path("stages").get(i).path("acknowledgedArtifactVersion").asInt()!=session.path("stages").get(i).path("currentArtifactVersion").asInt())throw V2Exception.conflict("V2_OPEN_ISSUES","请逐阶段确认当前未解决项");}acknowledge(session,4,body);session.put("state","COMPLETED");}var summary=session.putObject("summary").put("scopeNotice",early?"提前结束，未完成阶段明确列出；不生成完整能力评价。":"汇总当前产物、反馈与未解决项；不是能力证明，没有额外模型调用。");var stages=summary.putArray("stages");var incomplete=summary.putArray("incompleteStages");for(int i=0;i<5;i++){var s=session.path("stages").get(i);try{ready(session,i);var entry=stages.addObject().put("stageId",s.path("id").asText());entry.set("artifact",latest(s).deepCopy());}catch(ApiException e){incomplete.add(s.path("id").asText());}}session.put("endedAt",now());return db.save("v2_design_sessions",session,session.path("revision").asInt());}));}
    ObjectNode view(ObjectNode row){var out=row.deepCopy();for(JsonNode stage:out.path("stages")){if(stage.path("currentArtifactVersion").asInt()>0)((ObjectNode)stage).set("currentArtifact",latest(stage).deepCopy());for(JsonNode artifact:stage.path("artifactVersions"))publicArtifact((ObjectNode)artifact);if(stage.has("currentArtifact"))publicArtifact((ObjectNode)stage.path("currentArtifact"));}for(JsonNode stage:out.path("summary").path("stages"))publicArtifact((ObjectNode)stage.path("artifact"));return out;}
    void publicArtifact(ObjectNode artifact){if(artifact.has("protocol"))artifact.set("protocol",runner.llm.publicProtocol(artifact.path("protocol")));}
    public boolean supports(V2Task task){return task==V2Task.DESIGN_STAGE_EVALUATOR;}
    ObjectNode pending(ObjectNode row){return latest(stage(row,row.path("pendingStageId").asText()));}
    public void running(ObjectNode row,ObjectNode op){if(!row.path("state").asText().equals("IN_PROGRESS")||!row.path("pendingStageId").asText().equals(op.path("input").path("stageId").asText())||!pending(row).path("fields").equals(op.path("input").path("artifact")))throw V2Exception.conflict("V2_OPERATION_SUPERSEDED","阶段、产物或训练状态已变化，请读取最新训练");var stage=stage(row,row.path("pendingStageId").asText());stage.put("state","FEEDBACK_PENDING");var artifact=pending(row);artifact.put("operationId",op.path("id").asText()).put("feedbackStatus","PENDING");}
    public void failed(ObjectNode row,ObjectNode op,boolean interrupted){stage(row,row.path("pendingStageId").asText()).put("state",interrupted?"INTERRUPTED":"FEEDBACK_FAILED");pending(row).put("feedbackStatus",interrupted?"INTERRUPTED":"FAILED");}
    public void completed(ObjectNode row,ObjectNode result,ObjectNode op){var stage=stage(row,row.path("pendingStageId").asText());var artifact=pending(row);int index=STAGES.indexOf(stage.path("id").asText());if(!artifact.path("dependencies").equals(vector(row,index)))throw V2Exception.conflict("V2_OPERATION_SUPERSEDED","前序依赖已变，旧反馈不能提交");artifact.put("feedbackStatus","READY");artifact.set("feedback",result);artifact.set("protocol",op.path("protocol").deepCopy());stage.put("state","FEEDBACK_READY");}
}
